#include "core.hpp"
#include <iostream>
using namespace atlas;
int main(int argc,char**argv){try{if(argc<3){std::cout<<"ChatAtlas native core: demo/check/rebuild <directory>, backup <directory> <zip>\n";return 2;}std::string command=argv[1];fs::path root=path8(argv[2]);if(command!="demo"&&!fs::is_regular_file(root/"archive.sqlite3"))throw Error("這個資料夾還沒有收藏。");Store s(root);Control control;if(command=="demo"){DemoSource source(argc>=4&&std::string(argv[3])=="2"?2:1);auto result=collect(s,source,source.chats(),control);exportHtml(s);std::cout<<result.dump()<<"\n";}else if(command=="check"){auto problems=s.check();std::cout<<problems.dump()<<"\n";return problems.empty()?0:1;}else if(command=="rebuild"){exportHtml(s);std::cout<<"知識地圖已產生。\n";}else if(command=="backup"&&argc==4){makeZip(s,path8(argv[3]));std::cout<<"副本已保存。\n";}else return 2;return 0;}catch(const Error&e){std::cerr<<e.what()<<"\n";return 2;}catch(...){std::cerr<<"操作未完成，已保存的內容仍在。\n";return 2;}}
